-- ── next_serial ────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.next_serial(_kind text)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_prefix text;
  v_max integer;
  v_next integer;
BEGIN
  v_prefix := CASE _kind
    WHEN 'wholesale' THEN 'C'
    WHEN 'retail'    THEN 'R'
    WHEN 'supplier'  THEN 'S'
    WHEN 'hawlat'    THEN 'H'
    ELSE 'X'
  END;

  SELECT COALESCE(MAX(CAST(NULLIF(REGEXP_REPLACE(serial, '[^0-9]', '', 'g'), '') AS integer)), 0)
  INTO v_max
  FROM public.parties
  WHERE kind = _kind AND serial ~ '^[A-Z]?[0-9]+$';

  v_next := v_max + 1;
  RETURN v_prefix || LPAD(v_next::text, 3, '0');
END;
$$;

