-- ── has_role — search_path fix ─────────────────────────────
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  );
$$;

-- ── is_staff — search_path fix ─────────────────────────────
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role IN ('owner','moderator')
  );
$$;

-- ── confirm_memo — permission + bug fixes ──────────────────
-- Bug fixes:
--   1. Added is_staff() permission check
--   2. Uses base_quantity instead of quantity for stock deduction
--   3. cash_sale = paid amount (not total); credit entry for remainder
--   4. Inserts stock_movements log
CREATE OR REPLACE FUNCTION public.confirm_memo(_memo_id uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_memo RECORD;
  v_next_no integer;
  v_cash_amount numeric;
  v_credit_amount numeric;
BEGIN
  -- Permission check: শুধু staff confirm করতে পারবে
  IF NOT public.is_staff(auth.uid()) THEN
    RAISE EXCEPTION 'শুধু staff মেমো কনফার্ম করতে পারবেন';
  END IF;

  -- memo লক করে নাও
  SELECT * INTO v_memo FROM public.memos WHERE id = _memo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'মেমো পাওয়া যায়নি'; END IF;
  IF v_memo.status = 'confirmed' THEN
    RETURN COALESCE(v_memo.memo_no, 0);
  END IF;
  IF v_memo.status = 'void' THEN
    RAISE EXCEPTION 'বাতিল মেমো confirm করা যাবে না';
  END IF;

  -- পরবর্তী memo_no বের করো
  SELECT COALESCE(MAX(memo_no), 0) + 1 INTO v_next_no FROM public.memos WHERE status = 'confirmed';

  -- confirm করো
  UPDATE public.memos
  SET status = 'confirmed',
      memo_no = v_next_no,
      confirmed_at = now()
  WHERE id = _memo_id;

  -- cash_sale = paid amount (bug fix: আগে total দিচ্ছিল)
  v_cash_amount := COALESCE(v_memo.paid, 0);
  v_credit_amount := COALESCE(v_memo.total, 0) - v_cash_amount;

  -- নগদ বিক্রি এন্ট্রি
  IF v_cash_amount > 0 THEN
    INSERT INTO public.day_entries (entry_date, kind, amount, memo_id, name, details, party_id)
    VALUES (v_memo.memo_date, 'cash_sale', v_cash_amount, _memo_id,
            v_memo.shop_name, 'মেমো ' || v_next_no, v_memo.party_id);
  END IF;

  -- বাকি (credit) এন্ট্রি আলাদা
  IF v_credit_amount > 0 THEN
    INSERT INTO public.day_entries (entry_date, kind, amount, memo_id, name, details, party_id)
    VALUES (v_memo.memo_date, 'credit', v_credit_amount, _memo_id,
            v_memo.shop_name, 'বাকি — মেমো ' || v_next_no, v_memo.party_id);
  END IF;

  -- স্টক কাটো — base_quantity ব্যবহার করো (bug fix: আগে quantity ব্যবহার করত)
  UPDATE public.products p
  SET quantity = p.quantity - COALESCE(mi.base_quantity, mi.quantity)
  FROM public.memo_items mi
  WHERE mi.memo_id = _memo_id AND mi.product_id = p.id;

  -- stock_movements log করো
  INSERT INTO public.stock_movements (
    product_id, movement_type, quantity_change,
    quantity_before, quantity_after,
    reference_id, reference_type, note, created_by
  )
  SELECT
    mi.product_id,
    'sale',
    -COALESCE(mi.base_quantity, mi.quantity),
    p.quantity + COALESCE(mi.base_quantity, mi.quantity),
    p.quantity,
    _memo_id,
    'memo',
    'মেমো ' || v_next_no,
    auth.uid()
  FROM public.memo_items mi
  JOIN public.products p ON p.id = mi.product_id
  WHERE mi.memo_id = _memo_id AND mi.product_id IS NOT NULL;

  RETURN v_next_no;
END;
$$;

-- ── day_summary — search_path fix ──────────────────────────
CREATE OR REPLACE FUNCTION public.day_summary(_d date)
RETURNS TABLE(
  sales numeric,
  expenses numeric,
  deposits numeric,
  credits numeric,
  opening numeric,
  closing numeric,
  hawlat_due numeric,
  cash numeric
)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sales   numeric := 0;
  v_expenses numeric := 0;
  v_deposits numeric := 0;
  v_credits  numeric := 0;
  v_opening  numeric := 0;
  v_hawlat   numeric := 0;
BEGIN
  SELECT COALESCE(SUM(amount), 0) INTO v_sales    FROM public.day_entries WHERE entry_date = _d AND kind = 'cash_sale';
  SELECT COALESCE(SUM(amount), 0) INTO v_expenses  FROM public.day_entries WHERE entry_date = _d AND kind = 'expense';
  SELECT COALESCE(SUM(amount), 0) INTO v_deposits  FROM public.day_entries WHERE entry_date = _d AND kind = 'deposit';
  SELECT COALESCE(SUM(amount), 0) INTO v_credits   FROM public.day_entries WHERE entry_date = _d AND kind = 'credit';

  SELECT COALESCE(SUM(
    CASE
      WHEN kind IN ('cash_sale','deposit') THEN amount
      WHEN kind = 'expense' THEN -amount
      ELSE 0
    END
  ), 0)
  INTO v_opening
  FROM public.day_entries WHERE entry_date < _d;

  SELECT COALESCE(SUM(CASE WHEN kind = 'give' THEN amount ELSE -amount END), 0)
  INTO v_hawlat
  FROM public.hawlat_entries WHERE entry_date <= _d;

  sales      := v_sales;
  expenses   := v_expenses;
  deposits   := v_deposits;
  credits    := v_credits;
  opening    := v_opening;
  closing    := v_opening + v_sales + v_deposits - v_expenses;
  hawlat_due := v_hawlat;
  cash       := closing - v_hawlat;
  RETURN NEXT;
END;
$$;

