  FOR INSERT TO authenticated
  WITH CHECK (public.is_staff(auth.uid()));

-- UPDATE: শুধু draft memo edit করা যাবে (confirmed/void না)
DROP POLICY IF EXISTS "staff_update_draft_memos" ON public.memos;
CREATE POLICY "staff_update_draft_memos" ON public.memos
  FOR UPDATE TO authenticated
  USING (public.is_staff(auth.uid()) AND status = 'draft')
  WITH CHECK (public.is_staff(auth.uid()));

-- DELETE: শুধু owner
DROP POLICY IF EXISTS "owner_delete_memos" ON public.memos;
CREATE POLICY "owner_delete_memos" ON public.memos
  FOR DELETE TO authenticated
  USING (public.has_role(auth.uid(), 'owner'));
